(0, 'press_banca', '^press (de banca|inclinado|declinado|de pecho)', '(suelo|una mano|un brazo|landmine|guillotina|inverso)', 'pt', ARRAY['Junta as omoplatas e apoia-as no banco.', 'Desce devagar até tocar levemente no peito.', 'Pés bem firmes no chão durante toda a série.']::text[], ARRAY['Fazer ressaltar o peso no peito.', 'Levantar o rabo do banco ao empurrar.', 'Abrir demasiado os cotovelos (protege os ombros).']::text[]),
(1, 'sentadilla', '^sentadilla', '(pistol|salto|sissy|búlgara|isométric|lateral|cosaco|zercher|una pierna|un pie|hack|leñador|overhead|por encima|jefferson|frankenstein|pared|rana|hindú|press|curl|remo|patada|buenos días|trineo|colgado|explosiv|acostado)', 'es', ARRAY['Pies a la anchura de los hombros, puntas un poco hacia fuera.', 'Baja como si te sentaras, con el pecho alto.', 'Empuja el suelo con todo el pie para subir.']::text[], ARRAY['Juntar las rodillas hacia dentro.', 'Levantar los talones del suelo.', 'Redondear la espalda al bajar.']::text[]),
(1, 'sentadilla', '^sentadilla', '(pistol|salto|sissy|búlgara|isométric|lateral|cosaco|zercher|una pierna|un pie|hack|leñador|overhead|por encima|jefferson|frankenstein|pared|rana|hindú|press|curl|remo|patada|buenos días|trineo|colgado|explosiv|acostado)', 'en', ARRAY['Feet shoulder-width apart, toes slightly out.', 'Sit down and back, keeping your chest up.', 'Push the floor away with your whole foot.']::text[], ARRAY['Letting your knees cave in.', 'Lifting your heels off the floor.', 'Rounding your back on the way down.']::text[]),
(1, 'sentadilla', '^sentadilla', '(pistol|salto|sissy|búlgara|isométric|lateral|cosaco|zercher|una pierna|un pie|hack|leñador|overhead|por encima|jefferson|frankenstein|pared|rana|hindú|press|curl|remo|patada|buenos días|trineo|colgado|explosiv|acostado)', 'fr', ARRAY['Pieds à largeur d''épaules, pointes un peu vers l''extérieur.', 'Descends comme pour t''asseoir, poitrine haute.', 'Pousse le sol avec tout le pied pour remonter.']::text[], ARRAY['Laisser les genoux rentrer vers l''intérieur.', 'Décoller les talons du sol.', 'Arrondir le dos en descendant.']::text[]),
(1, 'sentadilla', '^sentadilla', '(pistol|salto|sissy|búlgara|isométric|lateral|cosaco|zercher|una pierna|un pie|hack|leñador|overhead|por encima|jefferson|frankenstein|pared|rana|hindú|press|curl|remo|patada|buenos días|trineo|colgado|explosiv|acostado)', 'pt', ARRAY['Pés à largura dos ombros, pontas ligeiramente para fora.', 'Desce como se te sentasses, com o peito alto.', 'Empurra o chão com o pé todo para subir.']::text[], ARRAY['Deixar os joelhos irem para dentro.', 'Levantar os calcanhares do chão.', 'Arredondar as costas ao descer.']::text[]),
(2, 'zancada', '^(zancadas?|sentadilla búlgara|subida al cajón)', '(salto|lateral|giro|press|curl)', 'es', ARRAY['Tronco recto y mirada al frente.', 'La rodilla de delante sigue la línea del pie.', 'Baja controlando y sube empujando con el talón de delante.']::text[], ARRAY['Dejar caer la rodilla hacia dentro.', 'Inclinar el tronco hacia delante.', 'Dar pasos tan cortos que la rodilla pasa mucho de la punta.']::text[]),
(2, 'zancada', '^(zancadas?|sentadilla búlgara|subida al cajón)', '(salto|lateral|giro|press|curl)', 'en', ARRAY['Keep your torso upright and look ahead.', 'Your front knee tracks over your foot.', 'Lower with control and drive up through your front heel.']::text[], ARRAY['Letting your knee collapse inward.', 'Leaning your torso forward.', 'Taking such short steps that your knee goes far past your toes.']::text[]),
(2, 'zancada', '^(zancadas?|sentadilla búlgara|subida al cajón)', '(salto|lateral|giro|press|curl)', 'fr', ARRAY['Buste droit, regard devant.', 'Le genou avant suit l''axe du pied.', 'Descends en contrôle et remonte en poussant sur le talon avant.']::text[], ARRAY['Laisser le genou partir vers l''intérieur.', 'Pencher le buste vers l''avant.', 'Faire des pas si courts que le genou dépasse beaucoup la pointe.']::text[]),
(2, 'zancada', '^(zancadas?|sentadilla búlgara|subida al cajón)', '(salto|lateral|giro|press|curl)', 'pt', ARRAY['Tronco direito e olhar em frente.', 'O joelho da frente segue a linha do pé.', 'Desce com controlo e sobe a empurrar com o calcanhar da frente.']::text[], ARRAY['Deixar o joelho cair para dentro.', 'Inclinar o tronco para a frente.', 'Dar passos tão curtos que o joelho passa muito da ponta do pé.']::text[]),
(3, 'peso_muerto', '^peso muerto', '(rumano|piernas rígidas|piernas rectas|una pierna|un pie|curl|remo|press|lateral|una mano|déficit)', 'es', ARRAY['La barra pegada a las piernas todo el recorrido.', 'Espalda recta: el esfuerzo sale de piernas y cadera.', 'Aprieta el abdomen antes de tirar.']::text[], ARRAY['Redondear la espalda al levantar.', 'Alejar la barra del cuerpo.', 'Tirar de golpe en vez de empujar el suelo.']::text[]),
(3, 'peso_muerto', '^peso muerto', '(rumano|piernas rígidas|piernas rectas|una pierna|un pie|curl|remo|press|lateral|una mano|déficit)', 'en', ARRAY['Keep the bar close to your legs the whole way.', 'Flat back: the work comes from legs and hips.', 'Brace your abs before you pull.']::text[], ARRAY['Rounding your back as you lift.', 'Letting the bar drift away from your body.', 'Yanking the bar instead of pushing the floor.']::text[]),
