(3, 'peso_muerto', '^peso muerto', '(rumano|piernas rígidas|piernas rectas|una pierna|un pie|curl|remo|press|lateral|una mano|déficit)', 'pt', ARRAY['A barra colada às pernas durante todo o movimento.', 'Costas direitas: o esforço vem das pernas e da anca.', 'Contrai o abdómen antes de puxar.']::text[], ARRAY['Arredondar as costas ao levantar.', 'Afastar a barra do corpo.', 'Puxar de repente em vez de empurrar o chão.']::text[]),
