(11, 'curl', '^curl (de bíceps|martillo|concentrado|en banco predicador|predicador)', '(tumbado|boca abajo|piernas|toalla|balón|botella|press|sentadilla|zottman)', 'pt', ARRAY['Cotovelos junto ao corpo e quietos.', 'Sobe sem mexer as costas.', 'Desce devagar até esticar o braço.']::text[], ARRAY['Balançar o tronco para subir o peso.', 'Levar os cotovelos para a frente.', 'Descer a meio ou de repente.']::text[]),
