(12, 'triceps', '^(extensión de tríceps|extensiones de tríceps|press francés|patada de tríceps)', '(una mano|un brazo|tumbado de lado|prono)', 'en', ARRAY['Keep your elbows still: only your forearm moves.', 'Fully straighten your arm and squeeze for a second.', 'Return slowly, without letting the weight drop.']::text[], ARRAY['Flaring your elbows out.', 'Moving your shoulder to help.', 'Going too heavy and cutting the range short.']::text[]),
(12, 'triceps', '^(extensión de tríceps|extensiones de tríceps|press francés|patada de tríceps)', '(una mano|un brazo|tumbado de lado|prono)', 'fr', ARRAY['Coudes immobiles : seul l''avant-bras bouge.', 'Tends complètement le bras et serre une seconde.', 'Reviens lentement, sans laisser tomber la charge.']::text[], ARRAY['Écarter les coudes vers l''extérieur.', 'Bouger l''épaule pour t''aider.', 'Prendre trop lourd et raccourcir le mouvement.']::text[]),
(12, 'triceps', '^(extensión de tríceps|extensiones de tríceps|press francés|patada de tríceps)', '(una mano|un brazo|tumbado de lado|prono)', 'pt', ARRAY['Cotovelos quietos: só o antebraço se mexe.', 'Estica o braço por completo e contrai um segundo.', 'Volta devagar, sem deixar cair o peso.']::text[], ARRAY['Abrir os cotovelos para fora.', 'Mexer o ombro para ajudar.', 'Usar peso a mais e encurtar o movimento.']::text[]),
(13, 'fondos', '^fondos', '(anillas|un brazo|rusos|coreanos|pierna|codos|suelo)', 'es', ARRAY['Hombros abajo, lejos de las orejas.', 'Baja hasta que el codo forme un ángulo recto.', 'Sube estirando los brazos sin bloquear de golpe.']::text[], ARRAY['Bajar demasiado y forzar el hombro.', 'Encoger los hombros.', 'Hacer el movimiento a tirones.']::text[]),
(13, 'fondos', '^fondos', '(anillas|un brazo|rusos|coreanos|pierna|codos|suelo)', 'en', ARRAY['Shoulders down, away from your ears.', 'Lower until your elbows are at a right angle.', 'Push up without snapping your elbows locked.']::text[], ARRAY['Going too deep and straining your shoulder.', 'Shrugging your shoulders.', 'Moving in jerks.']::text[]),
(13, 'fondos', '^fondos', '(anillas|un brazo|rusos|coreanos|pierna|codos|suelo)', 'fr', ARRAY['Épaules basses, loin des oreilles.', 'Descends jusqu''à un angle droit au coude.', 'Remonte en tendant les bras sans verrouiller d''un coup.']::text[], ARRAY['Descendre trop bas et forcer l''épaule.', 'Hausser les épaules.', 'Faire le mouvement par à-coups.']::text[]),
(13, 'fondos', '^fondos', '(anillas|un brazo|rusos|coreanos|pierna|codos|suelo)', 'pt', ARRAY['Ombros em baixo, longe das orelhas.', 'Desce até o cotovelo fazer um ângulo reto.', 'Sobe a esticar os braços sem trancar de repente.']::text[], ARRAY['Descer demasiado e forçar o ombro.', 'Encolher os ombros.', 'Fazer o movimento aos solavancos.']::text[]),
(14, 'flexiones', '^(flexión de brazos|flexiones)', '(pino|un brazo|una mano|dedos|arquero|palmada|explosiv|planche|hindú|spiderman|t$)', 'es', ARRAY['Cuerpo recto de la cabeza a los pies.', 'Manos un poco más abiertas que los hombros.', 'Baja hasta casi tocar el suelo con el pecho.']::text[], ARRAY['Hundir la cadera.', 'Subir el culo.', 'Hacer medio recorrido.']::text[]),
(14, 'flexiones', '^(flexión de brazos|flexiones)', '(pino|un brazo|una mano|dedos|arquero|palmada|explosiv|planche|hindú|spiderman|t$)', 'en', ARRAY['Body in a straight line from head to heels.', 'Hands slightly wider than your shoulders.', 'Lower until your chest nearly touches the floor.']::text[], ARRAY['Letting your hips sag.', 'Sticking your bum up.', 'Doing half reps.']::text[]),
(14, 'flexiones', '^(flexión de brazos|flexiones)', '(pino|un brazo|una mano|dedos|arquero|palmada|explosiv|planche|hindú|spiderman|t$)', 'fr', ARRAY['Corps aligné de la tête aux pieds.', 'Mains un peu plus écartées que les épaules.', 'Descends jusqu''à presque toucher le sol avec la poitrine.']::text[], ARRAY['Laisser tomber le bassin.', 'Lever les fesses.', 'Faire la moitié du mouvement.']::text[]),
(14, 'flexiones', '^(flexión de brazos|flexiones)', '(pino|un brazo|una mano|dedos|arquero|palmada|explosiv|planche|hindú|spiderman|t$)', 'pt', ARRAY['Corpo direito da cabeça aos pés.', 'Mãos um pouco mais abertas do que os ombros.', 'Desce até quase tocar o chão com o peito.']::text[], ARRAY['Deixar a anca descair.', 'Subir o rabo.', 'Fazer metade do movimento.']::text[]),
(15, 'plancha', '^plancha( abdominal)?( frontal)?( sobre (los )?antebrazos)?( con apoyo de rodillas| de rodillas)?$', NULL, 'es', ARRAY['Codos bajo los hombros.', 'Cuerpo recto: aprieta abdomen y glúteos.', 'Respira con calma; mejor menos tiempo bien hecho.']::text[], ARRAY['Dejar caer la cadera.', 'Subir mucho el culo.', 'Aguantar la respiración.']::text[]),
(15, 'plancha', '^plancha( abdominal)?( frontal)?( sobre (los )?antebrazos)?( con apoyo de rodillas| de rodillas)?$', NULL, 'en', ARRAY['Elbows under your shoulders.', 'Straight body: squeeze your abs and glutes.', 'Breathe calmly; a shorter hold done well is better.']::text[], ARRAY['Letting your hips drop.', 'Raising your bum too high.', 'Holding your breath.']::text[]),
(15, 'plancha', '^plancha( abdominal)?( frontal)?( sobre (los )?antebrazos)?( con apoyo de rodillas| de rodillas)?$', NULL, 'fr', ARRAY['Coudes sous les épaules.', 'Corps droit : serre abdos et fessiers.', 'Respire calmement ; mieux vaut moins longtemps mais bien.']::text[], ARRAY['Laisser tomber le bassin.', 'Monter trop les fesses.', 'Bloquer sa respiration.']::text[]),
(15, 'plancha', '^plancha( abdominal)?( frontal)?( sobre (los )?antebrazos)?( con apoyo de rodillas| de rodillas)?$', NULL, 'pt', ARRAY['Cotovelos por baixo dos ombros.', 'Corpo direito: contrai abdómen e glúteos.', 'Respira com calma; mais vale menos tempo bem feito.']::text[], ARRAY['Deixar a anca descair.', 'Subir demasiado o rabo.', 'Suster a respiração.']::text[]),
(16, 'plancha_lateral', '^plancha lateral', '(estrella|rotación|elevación|pierna)', 'es', ARRAY['Codo justo debajo del hombro.', 'Cadera alta, en línea con hombros y pies.', 'Mira al frente, no al suelo.']::text[], ARRAY['Dejar caer la cadera al suelo.', 'Echar el cuerpo hacia delante o hacia atrás.', 'Encoger el hombro de apoyo.']::text[]),
(16, 'plancha_lateral', '^plancha lateral', '(estrella|rotación|elevación|pierna)', 'en', ARRAY['Elbow right under your shoulder.', 'Hips high, in line with shoulders and feet.', 'Look ahead, not at the floor.']::text[], ARRAY['Letting your hips sink.', 'Rolling your body forward or back.', 'Shrugging the supporting shoulder.']::text[]),
(16, 'plancha_lateral', '^plancha lateral', '(estrella|rotación|elevación|pierna)', 'fr', ARRAY['Coude juste sous l''épaule.', 'Hanches hautes, alignées avec épaules et pieds.', 'Regarde devant, pas le sol.']::text[], ARRAY['Laisser les hanches tomber.', 'Basculer le corps vers l''avant ou l''arrière.', 'Hausser l''épaule d''appui.']::text[]),
(16, 'plancha_lateral', '^plancha lateral', '(estrella|rotación|elevación|pierna)', 'pt', ARRAY['Cotovelo mesmo por baixo do ombro.', 'Anca alta, em linha com ombros e pés.', 'Olha em frente, não para o chão.']::text[], ARRAY['Deixar a anca cair.', 'Inclinar o corpo para a frente ou para trás.', 'Encolher o ombro de apoio.']::text[]),
(17, 'crunch', '^(crunch|encogimiento abdominal|recogimiento abdominal)', '(rana|bicicleta|lateral|oblicuo|inverso|polea|botella|balón|v$)', 'es', ARRAY['Sube despegando los hombros, no tirando del cuello.', 'Suelta el aire al subir.', 'Baja despacio sin relajar del todo.']::text[], ARRAY['Tirar de la cabeza con las manos.', 'Subir con impulso.', 'Hacer muchas repeticiones rápidas y mal.']::text[]),
(17, 'crunch', '^(crunch|encogimiento abdominal|recogimiento abdominal)', '(rana|bicicleta|lateral|oblicuo|inverso|polea|botella|balón|v$)', 'en', ARRAY['Lift your shoulders, don''t pull on your neck.', 'Breathe out as you come up.', 'Lower slowly without fully relaxing.']::text[], ARRAY['Pulling your head with your hands.', 'Using momentum to come up.', 'Doing lots of fast, sloppy reps.']::text[]),
(17, 'crunch', '^(crunch|encogimiento abdominal|recogimiento abdominal)', '(rana|bicicleta|lateral|oblicuo|inverso|polea|botella|balón|v$)', 'fr', ARRAY['Décolle les épaules, ne tire pas sur la nuque.', 'Expire en montant.', 'Redescends lentement sans tout relâcher.']::text[], ARRAY['Tirer la tête avec les mains.', 'Monter avec de l''élan.', 'Enchaîner des répétitions rapides et mal faites.']::text[]),
(17, 'crunch', '^(crunch|encogimiento abdominal|recogimiento abdominal)', '(rana|bicicleta|lateral|oblicuo|inverso|polea|botella|balón|v$)', 'pt', ARRAY['Sobe a descolar os ombros, sem puxar o pescoço.', 'Solta o ar ao subir.', 'Desce devagar sem relaxar por completo.']::text[], ARRAY['Puxar a cabeça com as mãos.', 'Subir com impulso.', 'Fazer muitas repetições rápidas e mal feitas.']::text[]),
(18, 'elevacion_piernas', '^elevaci(ón|ones) de piernas', '(lateral|una pierna|polea)', 'es', ARRAY['Aprieta el abdomen antes de mover las piernas.', 'Sube y baja despacio, sin balanceo.', 'Si estás tumbado, la zona lumbar pegada al apoyo.']::text[], ARRAY['Usar impulso para subir las piernas.', 'Arquear la zona lumbar.', 'Dejar caer las piernas de golpe.']::text[]),
(18, 'elevacion_piernas', '^elevaci(ón|ones) de piernas', '(lateral|una pierna|polea)', 'en', ARRAY['Brace your abs before moving your legs.', 'Raise and lower slowly, no swinging.', 'If lying down, keep your lower back on the surface.']::text[], ARRAY['Swinging your legs up.', 'Arching your lower back.', 'Dropping your legs down.']::text[]),
(18, 'elevacion_piernas', '^elevaci(ón|ones) de piernas', '(lateral|una pierna|polea)', 'fr', ARRAY['Gaine les abdos avant de bouger les jambes.', 'Monte et descends lentement, sans balancer.', 'Allongé, garde le bas du dos collé au support.']::text[], ARRAY['Prendre de l''élan pour monter les jambes.', 'Cambrer le bas du dos.', 'Laisser retomber les jambes d''un coup.']::text[]),
(18, 'elevacion_piernas', '^elevaci(ón|ones) de piernas', '(lateral|una pierna|polea)', 'pt', ARRAY['Contrai o abdómen antes de mexer as pernas.', 'Sobe e desce devagar, sem balançar.', 'Deitado, mantém a zona lombar colada ao apoio.']::text[], ARRAY['Usar impulso para subir as pernas.', 'Arquear a zona lombar.', 'Deixar cair as pernas de repente.']::text[]),
(19, 'prensa', '^prensa de piernas', '(gemelos|una pierna)', 'es', ARRAY['Espalda y culo bien apoyados en el respaldo.', 'Rodillas en la línea de los pies.', 'Baja hasta donde no se despegue la cadera.']::text[], ARRAY['Bloquear las rodillas de golpe arriba.', 'Bajar tanto que se levanta el culo del asiento.', 'Juntar las rodillas al empujar.']::text[]),
(19, 'prensa', '^prensa de piernas', '(gemelos|una pierna)', 'en', ARRAY['Back and bum flat against the pad.', 'Knees in line with your feet.', 'Lower only as far as your hips stay down.']::text[], ARRAY['Snapping your knees locked at the top.', 'Going so deep your bum lifts off the seat.', 'Letting your knees cave in as you push.']::text[]),
(19, 'prensa', '^prensa de piernas', '(gemelos|una pierna)', 'fr', ARRAY['Dos et fesses bien appuyés sur le dossier.', 'Genoux dans l''axe des pieds.', 'Descends tant que le bassin ne décolle pas.']::text[], ARRAY['Verrouiller les genoux d''un coup en haut.', 'Descendre si bas que les fesses décollent.', 'Serrer les genoux en poussant.']::text[]),
(19, 'prensa', '^prensa de piernas', '(gemelos|una pierna)', 'pt', ARRAY['Costas e rabo bem apoiados no encosto.', 'Joelhos na linha dos pés.', 'Desce até onde a anca não descola.']::text[], ARRAY['Trancar os joelhos de repente lá em cima.', 'Descer tanto que o rabo se levanta do assento.', 'Juntar os joelhos ao empurrar.']::text[]),
(20, 'extension_cuadriceps', '^extensi(ón|ones) de (cuádriceps|piernas)', '(una pierna)', 'es', ARRAY['Ajusta el asiento: la rodilla en el eje de la máquina.', 'Estira las piernas y aprieta un segundo.', 'Baja despacio, sin que choquen las pesas.']::text[], ARRAY['Dar patadas con impulso.', 'Levantar el culo del asiento.', 'Usar tanto peso que no estiras del todo.']::text[]),
(20, 'extension_cuadriceps', '^extensi(ón|ones) de (cuádriceps|piernas)', '(una pierna)', 'en', ARRAY['Set the seat so your knee lines up with the machine''s pivot.', 'Straighten your legs and squeeze for a second.', 'Lower slowly, without the weights clanking.']::text[], ARRAY['Kicking the weight up.', 'Lifting your bum off the seat.', 'Going so heavy you can''t fully straighten.']::text[]),
(20, 'extension_cuadriceps', '^extensi(ón|ones) de (cuádriceps|piernas)', '(una pierna)', 'fr', ARRAY['Règle le siège : genou dans l''axe de la machine.', 'Tends les jambes et serre une seconde.', 'Redescends lentement, sans faire claquer les poids.']::text[], ARRAY['Donner des coups de pied avec élan.', 'Décoller les fesses du siège.', 'Prendre si lourd que tu ne tends pas complètement.']::text[]),
(20, 'extension_cuadriceps', '^extensi(ón|ones) de (cuádriceps|piernas)', '(una pierna)', 'pt', ARRAY['Ajusta o assento: o joelho no eixo da máquina.', 'Estica as pernas e contrai um segundo.', 'Desce devagar, sem bater os pesos.']::text[], ARRAY['Dar pontapés com impulso.', 'Levantar o rabo do assento.', 'Usar tanto peso que não esticas por completo.']::text[]),
(21, 'curl_femoral', '^curl femoral', '(inverso|nórdico|patada|balón|toalla|anillas|cuadrupedia)', 'es', ARRAY['Cadera pegada al banco o al asiento.', 'Dobla las rodillas hasta el final y aprieta.', 'Vuelve despacio hasta casi estirar.']::text[], ARRAY['Levantar la cadera para ayudarte.', 'Hacer el movimiento con impulso.', 'Bajar de golpe.']::text[]),
(21, 'curl_femoral', '^curl femoral', '(inverso|nórdico|patada|balón|toalla|anillas|cuadrupedia)', 'en', ARRAY['Hips pressed into the bench or seat.', 'Bend your knees all the way and squeeze.', 'Return slowly until almost straight.']::text[], ARRAY['Lifting your hips to help.', 'Using momentum.', 'Letting the weight drop.']::text[]),
(21, 'curl_femoral', '^curl femoral', '(inverso|nórdico|patada|balón|toalla|anillas|cuadrupedia)', 'fr', ARRAY['Bassin collé au banc ou au siège.', 'Plie les genoux jusqu''au bout et serre.', 'Reviens lentement jusqu''à presque tendre.']::text[], ARRAY['Lever le bassin pour t''aider.', 'Faire le mouvement avec élan.', 'Redescendre d''un coup.']::text[]),
(21, 'curl_femoral', '^curl femoral', '(inverso|nórdico|patada|balón|toalla|anillas|cuadrupedia)', 'pt', ARRAY['Anca colada ao banco ou ao assento.', 'Dobra os joelhos até ao fim e contrai.', 'Volta devagar até quase esticar.']::text[], ARRAY['Levantar a anca para ajudar.', 'Fazer o movimento com impulso.', 'Descer de repente.']::text[]),
(22, 'gemelos', '^(elevaci(ón|ones) de (gemelos|talones)|prensa de gemelos)', NULL, 'es', ARRAY['Sube todo lo que puedas sobre las puntas.', 'Para un segundo arriba.', 'Baja despacio hasta notar el estiramiento.']::text[], ARRAY['Rebotar abajo.', 'Hacer recorridos muy cortos.', 'Doblar las rodillas para ayudarte.']::text[]),
(22, 'gemelos', '^(elevaci(ón|ones) de (gemelos|talones)|prensa de gemelos)', NULL, 'en', ARRAY['Rise as high as you can onto your toes.', 'Pause for a second at the top.', 'Lower slowly until you feel the stretch.']::text[], ARRAY['Bouncing at the bottom.', 'Doing very short reps.', 'Bending your knees to help.']::text[]),
(22, 'gemelos', '^(elevaci(ón|ones) de (gemelos|talones)|prensa de gemelos)', NULL, 'fr', ARRAY['Monte le plus haut possible sur la pointe des pieds.', 'Marque une pause d''une seconde en haut.', 'Redescends lentement jusqu''à sentir l''étirement.']::text[], ARRAY['Rebondir en bas.', 'Faire des mouvements très courts.', 'Plier les genoux pour t''aider.']::text[]),
(22, 'gemelos', '^(elevaci(ón|ones) de (gemelos|talones)|prensa de gemelos)', NULL, 'pt', ARRAY['Sobe o mais que puderes nas pontas dos pés.', 'Faz uma pausa de um segundo lá em cima.', 'Desce devagar até sentir o alongamento.']::text[], ARRAY['Ressaltar em baixo.', 'Fazer movimentos muito curtos.', 'Dobrar os joelhos para ajudar.']::text[]),
(23, 'face_pull', '^face pull', NULL, 'es', ARRAY['Tira de la cuerda hacia la cara, con los codos altos.', 'Separa las manos al final del tirón.', 'Vuelve despacio, sin que te arrastre.']::text[], ARRAY['Echar el cuerpo hacia atrás para tirar.', 'Bajar los codos.', 'Usar demasiado peso.']::text[]),
(23, 'face_pull', '^face pull', NULL, 'en', ARRAY['Pull the rope towards your face, elbows high.', 'Pull your hands apart at the end.', 'Return slowly, without being dragged forward.']::text[], ARRAY['Leaning back to pull.', 'Dropping your elbows.', 'Going too heavy.']::text[]),
(23, 'face_pull', '^face pull', NULL, 'fr', ARRAY['Tire la corde vers le visage, coudes hauts.', 'Écarte les mains en fin de tirage.', 'Reviens lentement, sans te laisser entraîner.']::text[], ARRAY['Se pencher en arrière pour tirer.', 'Baisser les coudes.', 'Prendre trop lourd.']::text[]),
(23, 'face_pull', '^face pull', NULL, 'pt', ARRAY['Puxa a corda em direção à cara, com os cotovelos altos.', 'Afasta as mãos no fim do movimento.', 'Volta devagar, sem te deixares arrastar.']::text[], ARRAY['Inclinar o corpo para trás para puxar.', 'Baixar os cotovelos.', 'Usar peso a mais.']::text[]),
(24, 'aperturas', '^aperturas', '(invers|deltoides posterior|de pie con peso corporal|tumbado en el suelo|una mano|un brazo)', 'es', ARRAY['Codos un poco doblados y fijos, como abrazando un árbol.', 'Abre hasta notar el pecho estirado, sin forzar.', 'Cierra apretando el pecho.']::text[], ARRAY['Estirar del todo los codos.', 'Bajar demasiado y forzar el hombro.', 'Convertirlo en un press doblando los brazos.']::text[]),
(24, 'aperturas', '^aperturas', '(invers|deltoides posterior|de pie con peso corporal|tumbado en el suelo|una mano|un brazo)', 'en', ARRAY['Elbows slightly bent and fixed, like hugging a tree.', 'Open until you feel your chest stretch, without forcing.', 'Bring your hands together by squeezing your chest.']::text[], ARRAY['Locking your elbows straight.', 'Going too low and straining your shoulder.', 'Turning it into a press by bending your arms.']::text[]),
(24, 'aperturas', '^aperturas', '(invers|deltoides posterior|de pie con peso corporal|tumbado en el suelo|una mano|un brazo)', 'fr', ARRAY['Coudes légèrement fléchis et fixes, comme pour enlacer un arbre.', 'Ouvre jusqu''à sentir l''étirement des pectoraux, sans forcer.', 'Referme en serrant la poitrine.']::text[], ARRAY['Tendre complètement les coudes.', 'Descendre trop et forcer l''épaule.', 'En faire un développé en pliant les bras.']::text[]),
(24, 'aperturas', '^aperturas', '(invers|deltoides posterior|de pie con peso corporal|tumbado en el suelo|una mano|un brazo)', 'pt', ARRAY['Cotovelos ligeiramente fletidos e fixos, como a abraçar uma árvore.', 'Abre até sentir o peito alongado, sem forçar.', 'Fecha a contrair o peito.']::text[], ARRAY['Esticar por completo os cotovelos.', 'Descer demasiado e forçar o ombro.', 'Transformá-lo num press dobrando os braços.']::text[]),
(25, 'burpee', '^burpee', NULL, 'es', ARRAY['Ve a tu ritmo: mejor seguido que rápido.', 'Al bajar, apoya las manos y lleva los pies atrás con control.', 'Aterriza suave, con las rodillas un poco dobladas.']::text[], ARRAY['Hundir la cadera al estar en plancha.', 'Caer de golpe al suelo.', 'Aguantar la respiración.']::text[]),
(25, 'burpee', '^burpee', NULL, 'en', ARRAY['Find your pace: steady beats fast.', 'Plant your hands and step or jump your feet back with control.', 'Land softly with slightly bent knees.']::text[], ARRAY['Letting your hips sag in the plank.', 'Crashing down to the floor.', 'Holding your breath.']::text[]),
(25, 'burpee', '^burpee', NULL, 'fr', ARRAY['Trouve ton rythme : régulier vaut mieux que rapide.', 'En descendant, pose les mains et recule les pieds en contrôle.', 'Réceptionne-toi en douceur, genoux un peu fléchis.']::text[], ARRAY['Laisser tomber le bassin en planche.', 'Se laisser tomber au sol.', 'Bloquer sa respiration.']::text[]),
(25, 'burpee', '^burpee', NULL, 'pt', ARRAY['Vai ao teu ritmo: mais vale seguido do que rápido.', 'Ao descer, apoia as mãos e leva os pés para trás com controlo.', 'Aterra suavemente, com os joelhos ligeiramente fletidos.']::text[], ARRAY['Deixar a anca descair na prancha.', 'Cair de repente no chão.', 'Suster a respiração.']::text[]),
(26, 'escalador', '^(escalador|mountain climber)', NULL, 'es', ARRAY['Manos bajo los hombros y cuerpo recto.', 'Lleva las rodillas al pecho alternando.', 'Mantén la cadera baja y quieta.']::text[], ARRAY['Subir el culo.', 'Mover los hombros por delante de las manos.', 'Ir tan rápido que pierdes la postura.']::text[]),
(26, 'escalador', '^(escalador|mountain climber)', NULL, 'en', ARRAY['Hands under shoulders, body straight.', 'Drive your knees to your chest, alternating.', 'Keep your hips low and steady.']::text[], ARRAY['Sticking your bum up.', 'Shifting your shoulders past your hands.', 'Going so fast you lose your form.']::text[]),
(26, 'escalador', '^(escalador|mountain climber)', NULL, 'fr', ARRAY['Mains sous les épaules, corps droit.', 'Ramène les genoux vers la poitrine en alternant.', 'Garde le bassin bas et stable.']::text[], ARRAY['Lever les fesses.', 'Avancer les épaules devant les mains.', 'Aller si vite que tu perds la posture.']::text[]),
(26, 'escalador', '^(escalador|mountain climber)', NULL, 'pt', ARRAY['Mãos por baixo dos ombros e corpo direito.', 'Leva os joelhos ao peito, alternando.', 'Mantém a anca baixa e quieta.']::text[], ARRAY['Subir o rabo.', 'Passar os ombros à frente das mãos.', 'Ir tão depressa que perdes a postura.']::text[]),
(27, 'comba', '^(salto a la comba|saltar a la comba|salto de comba)', NULL, 'es', ARRAY['Saltos pequeños, sobre las puntas de los pies.', 'Gira la cuerda con las muñecas, no con los brazos.', 'Codos cerca del cuerpo.']::text[], ARRAY['Saltar demasiado alto.', 'Caer sobre los talones.', 'Mover los brazos enteros.']::text[]),
(27, 'comba', '^(salto a la comba|saltar a la comba|salto de comba)', NULL, 'en', ARRAY['Small jumps, on the balls of your feet.', 'Turn the rope with your wrists, not your arms.', 'Keep your elbows close to your body.']::text[], ARRAY['Jumping too high.', 'Landing on your heels.', 'Swinging your whole arms.']::text[]),
(27, 'comba', '^(salto a la comba|saltar a la comba|salto de comba)', NULL, 'fr', ARRAY['Petits sauts sur l''avant des pieds.', 'Fais tourner la corde avec les poignets, pas les bras.', 'Coudes près du corps.']::text[], ARRAY['Sauter trop haut.', 'Retomber sur les talons.', 'Bouger les bras entiers.']::text[]),
(27, 'comba', '^(salto a la comba|saltar a la comba|salto de comba)', NULL, 'pt', ARRAY['Saltos pequenos, nas pontas dos pés.', 'Roda a corda com os pulsos, não com os braços.', 'Cotovelos junto ao corpo.']::text[], ARRAY['Saltar demasiado alto.', 'Cair nos calcanhares.', 'Mexer os braços inteiros.']::text[]),
(28, 'cinta', '^(carrera en cinta|correr en cinta|caminar en cinta|caminata en cinta)', NULL, 'es', ARRAY['Empieza suave unos minutos y ve subiendo.', 'Pasos cortos y ligeros, con la mirada al frente.', 'Un ritmo al que podrías decir una frase.']::text[], ARRAY['Agarrarte a las barras todo el rato.', 'Dar zancadas muy largas.', 'Empezar demasiado rápido.']::text[]),
(28, 'cinta', '^(carrera en cinta|correr en cinta|caminar en cinta|caminata en cinta)', NULL, 'en', ARRAY['Start easy for a few minutes, then build up.', 'Short, light steps, eyes forward.', 'A pace at which you could say a sentence.']::text[], ARRAY['Holding the rails the whole time.', 'Taking very long strides.', 'Starting too fast.']::text[]),
(28, 'cinta', '^(carrera en cinta|correr en cinta|caminar en cinta|caminata en cinta)', NULL, 'fr', ARRAY['Commence doucement quelques minutes puis accélère.', 'Petits pas légers, regard devant.', 'Un rythme où tu pourrais dire une phrase.']::text[], ARRAY['Se tenir aux barres tout le temps.', 'Faire de très grandes foulées.', 'Partir trop vite.']::text[]),
(28, 'cinta', '^(carrera en cinta|correr en cinta|caminar en cinta|caminata en cinta)', NULL, 'pt', ARRAY['Começa devagar alguns minutos e vai subindo.', 'Passos curtos e leves, olhar em frente.', 'Um ritmo a que conseguirias dizer uma frase.']::text[], ARRAY['Agarrar-te às barras o tempo todo.', 'Dar passadas muito longas.', 'Começar depressa demais.']::text[]),
(29, 'bici', '^(ciclismo indoor|bicicleta estática|ciclismo en bicicleta estática)', NULL, 'es', ARRAY['Ajusta el sillín: la pierna casi estirada abajo.', 'Espalda recta y hombros relajados.', 'Pedalea redondo, empujando y tirando.']::text[], ARRAY['Sillín demasiado bajo (sufren las rodillas).', 'Cargar el peso en las manos.', 'Ir a tope desde el principio.']::text[]),
(29, 'bici', '^(ciclismo indoor|bicicleta estática|ciclismo en bicicleta estática)', NULL, 'en', ARRAY['Set the saddle so your leg is almost straight at the bottom.', 'Straight back, relaxed shoulders.', 'Pedal in smooth circles, pushing and pulling.']::text[], ARRAY['Saddle too low (hard on your knees).', 'Leaning your weight on your hands.', 'Going all out from the start.']::text[]),
(29, 'bici', '^(ciclismo indoor|bicicleta estática|ciclismo en bicicleta estática)', NULL, 'fr', ARRAY['Règle la selle : jambe presque tendue en bas.', 'Dos droit, épaules détendues.', 'Pédale en rond, en poussant et en tirant.']::text[], ARRAY['Selle trop basse (les genoux souffrent).', 'Mettre le poids sur les mains.', 'Partir à fond dès le début.']::text[]),
(29, 'bici', '^(ciclismo indoor|bicicleta estática|ciclismo en bicicleta estática)', NULL, 'pt', ARRAY['Ajusta o selim: a perna quase esticada em baixo.', 'Costas direitas e ombros relaxados.', 'Pedala de forma redonda, a empurrar e a puxar.']::text[], ARRAY['Selim demasiado baixo (sofrem os joelhos).', 'Pôr o peso nas mãos.', 'Ir ao máximo desde o início.']::text[]),
(30, 'saltos_tijera', '^(jumping jacks?|saltos? de tijera)', NULL, 'es', ARRAY['Aterriza suave sobre las puntas.', 'Brazos y piernas se abren a la vez.', 'Abdomen firme para no balancearte.']::text[], ARRAY['Caer con las piernas rígidas.', 'Llevar un ritmo que no puedes mantener.', 'Doblar la espalda.']::text[]),
(30, 'saltos_tijera', '^(jumping jacks?|saltos? de tijera)', NULL, 'en', ARRAY['Land softly on the balls of your feet.', 'Arms and legs open at the same time.', 'Tight core so you don''t sway.']::text[], ARRAY['Landing with stiff legs.', 'Going at a pace you can''t keep.', 'Hunching your back.']::text[]),
(30, 'saltos_tijera', '^(jumping jacks?|saltos? de tijera)', NULL, 'fr', ARRAY['Réceptionne-toi en douceur sur l''avant des pieds.', 'Bras et jambes s''ouvrent en même temps.', 'Abdos gainés pour ne pas te balancer.']::text[], ARRAY['Retomber jambes raides.', 'Prendre un rythme impossible à tenir.', 'Courber le dos.']::text[]),
(30, 'saltos_tijera', '^(jumping jacks?|saltos? de tijera)', NULL, 'pt', ARRAY['Aterra suavemente nas pontas dos pés.', 'Braços e pernas abrem ao mesmo tempo.', 'Abdómen firme para não balançares.']::text[], ARRAY['Cair com as pernas rígidas.', 'Levar um ritmo que não consegues manter.', 'Curvar as costas.']::text[]),
(31, 'swing', '^swing (ruso |americano )?con kettlebell', '(una mano|un brazo)', 'es', ARRAY['El impulso sale de la cadera, no de los brazos.', 'Lleva la cadera atrás y luego hacia delante con fuerza.', 'Espalda recta todo el movimiento.']::text[], ARRAY['Subir la pesa con los brazos.', 'Convertirlo en una sentadilla.', 'Redondear la espalda al bajar.']::text[]),
(31, 'swing', '^swing (ruso |americano )?con kettlebell', '(una mano|un brazo)', 'en', ARRAY['The power comes from your hips, not your arms.', 'Hinge your hips back, then snap them forward.', 'Flat back the whole time.']::text[], ARRAY['Lifting the kettlebell with your arms.', 'Turning it into a squat.', 'Rounding your back on the way down.']::text[]),
(31, 'swing', '^swing (ruso |americano )?con kettlebell', '(una mano|un brazo)', 'fr', ARRAY['L''élan vient des hanches, pas des bras.', 'Recule les hanches puis pousse-les fort vers l''avant.', 'Dos droit tout le mouvement.']::text[], ARRAY['Monter la kettlebell avec les bras.', 'En faire un squat.', 'Arrondir le dos en descendant.']::text[]),
(31, 'swing', '^swing (ruso |americano )?con kettlebell', '(una mano|un brazo)', 'pt', ARRAY['O impulso vem da anca, não dos braços.', 'Leva a anca para trás e depois para a frente com força.', 'Costas direitas durante todo o movimento.']::text[], ARRAY['Subir o kettlebell com os braços.', 'Transformá-lo num agachamento.', 'Arredondar as costas ao descer.']::text[]),
(32, 'lumbar', '^(hiperextensi(ón|ones)|extensi(ón|ones) lumbar|superman)', '(invers|una pierna)', 'es', ARRAY['Sube hasta que el cuerpo quede en línea, no más.', 'Mueve la cadera, con la espalda recta.', 'Hazlo despacio y sin tirones.']::text[], ARRAY['Arquear de más al subir.', 'Hacerlo con impulso.', 'Mover el cuello hacia atrás.']::text[]),
(32, 'lumbar', '^(hiperextensi(ón|ones)|extensi(ón|ones) lumbar|superman)', '(invers|una pierna)', 'en', ARRAY['Rise until your body is in a straight line, no further.', 'Move from your hips with a flat back.', 'Go slowly, no jerking.']::text[], ARRAY['Over-arching at the top.', 'Using momentum.', 'Throwing your head back.']::text[]),
(32, 'lumbar', '^(hiperextensi(ón|ones)|extensi(ón|ones) lumbar|superman)', '(invers|una pierna)', 'fr', ARRAY['Monte jusqu''à ce que le corps soit aligné, pas plus.', 'Bouge depuis les hanches, dos droit.', 'Fais-le lentement, sans à-coups.']::text[], ARRAY['Trop cambrer en montant.', 'Le faire avec élan.', 'Basculer la nuque vers l''arrière.']::text[]),
(32, 'lumbar', '^(hiperextensi(ón|ones)|extensi(ón|ones) lumbar|superman)', '(invers|una pierna)', 'pt', ARRAY['Sobe até o corpo ficar em linha, não mais.', 'Mexe a anca, com as costas direitas.', 'Fá-lo devagar e sem solavancos.']::text[], ARRAY['Arquear de mais ao subir.', 'Fazê-lo com impulso.', 'Levar o pescoço para trás.']::text[])
) AS f(orden, familia, patron, excluir, idioma, claves, errores)
  ON e.nombre ~* f.patron AND (f.excluir IS NULL OR e.nombre !~* f.excluir)
WHERE NOT EXISTS (SELECT 1 FROM consejos_ejercicio c WHERE c.ejercicio_id = e.id AND c.idioma = f.idioma)
ORDER BY e.id, f.idioma, f.orden;
